changeSet.sql:
insert into dokumentart (code, name, beschreibung, gruppen, pflichtfelder, zusatz_schema, vertraulichkeit,
    aufbewahrung_jahre, aufbewahrung_ab, gesetzliche_pflicht, aktiv, selbst_ausgestellt,
    belegnummer_muster, ki_vorschlag, ki_felder, reihenfolge)
values ('WISSENSQUELLE', 'Wissensquelle',
    'Fachunterlage, deren Inhalt als Quelle für die Wissensbasis dient.',
    array['frei']::text[], array['titel', 'datum']::text[],
    case when current_schema() = 'm_vhf_gsk' then '{
        "type": "object",
        "properties": {
            "herausgeber": {"type": "string", "minLength": 1},
            "verband": {
                "type": "array",
                "items": {"type": "string", "enum": ["vhf", "gsk"]},
                "x-labels": {"vhf": "VHF", "gsk": "GSK"},
                "minItems": 1,
                "uniqueItems": true
            },
            "zugriff": {
                "type": "string",
                "enum": ["oeffentlich", "mitglieder", "vorstand"],
                "default": "mitglieder"
            },
            "veroeffentlicht": {"type": "boolean", "default": false}
        },
        "required": ["verband", "zugriff", "veroeffentlicht"],
        "additionalProperties": false
    }'::jsonb else '{
        "type": "object",
        "properties": {"herausgeber": {"type": "string", "minLength": 1}},
        "additionalProperties": false
    }'::jsonb end,
    'NORMAL', null, null, false, true, false, '{}'::text[], false, '{}'::text[], 0);
